// Uses MODEL from model.js (generated by train_model.py from the dataset).
const LABELS = {
  Age: "Age (years)", Gender: "Sex", TB: "Total bilirubin (mg/dL)",
  DB: "Direct bilirubin (mg/dL)", Alkphos: "Alkaline phosphatase (IU/L)",
  Sgpt: "ALT / Sgpt (IU/L)", Sgot: "AST / Sgot (IU/L)",
  TP: "Total proteins (g/dL)", ALB: "Albumin (g/dL)", AG: "Albumin/globulin ratio"
};
const STEP = { TB: 0.1, DB: 0.1, TP: 0.1, ALB: 0.1, AG: 0.01 };
const LIKELY_PATIENT = [55, 1, 8.5, 4.2, 450, 180, 220, 5.8, 2.6, 0.7];
const LIKELY_HEALTHY = [30, 0, 0.7, 0.1, 180, 22, 25, 7.2, 4.2, 1.2];

const box = document.getElementById("fields");
MODEL.features.forEach((f, i) => {
  const wrap = document.createElement("div");
  const control = f === "Gender"
    ? `<select id="f${i}"><option value="1">Male</option><option value="0">Female</option></select>`
    : `<input id="f${i}" type="number" inputmode="decimal" min="0" step="${STEP[f] || 1}" value="${MODEL.median[i]}">`;
  wrap.innerHTML = `<label for="f${i}">${LABELS[f]}</label>${control}`;
  box.appendChild(wrap);
});

const m = MODEL.metrics;
document.getElementById("info").textContent =
  `Model: logistic regression trained on the Indian Liver Patient Dataset (UCI), ${m.train} training records. ` +
  `On ${m.test} held-out patients: accuracy ${(m.accuracy * 100).toFixed(1)}%, recall ${(m.recall * 100).toFixed(1)}%. ` +
  `It will miss some patients and flag some healthy people.`;

function fill(values) {
  values.forEach((v, i) => { document.getElementById("f" + i).value = v; });
  calculate();
}

function calculate() {
  let z = MODEL.intercept;
  const parts = [];
  for (let i = 0; i < MODEL.features.length; i++) {
    const v = parseFloat(document.getElementById("f" + i).value);
    if (isNaN(v)) { alert("Please fill in: " + LABELS[MODEL.features[i]]); return; }
    const c = MODEL.coef[i] * (v - MODEL.mean[i]) / MODEL.scale[i];
    z += c;
    parts.push([LABELS[MODEL.features[i]], c]);
  }
  const p = 1 / (1 + Math.exp(-z));

  document.getElementById("empty").hidden = true;
  document.getElementById("res").hidden = false;
  document.getElementById("pct").textContent = Math.round(p * 100) + "%";

  const band = document.getElementById("band");
  if (p >= 0.6) { band.textContent = "Pattern is closer to patients with liver disease"; band.style.color = "var(--up)"; }
  else if (p >= 0.4) { band.textContent = "Unclear: the pattern sits between the two groups"; band.style.color = "var(--mid)"; }
  else { band.textContent = "Pattern is closer to people without liver disease"; band.style.color = "var(--down)"; }

  document.getElementById("pin").style.left = `calc(${p * 100}% - 2px)`;

  parts.sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
  document.getElementById("why").innerHTML = parts.slice(0, 4).map(([name, c]) =>
    `<li><span>${name}</span><span class="${c > 0 ? "u" : "d"}">${c > 0 ? "raises" : "lowers"} the estimate</span></li>`
  ).join("");
}

document.getElementById("go").onclick = calculate;
document.getElementById("ex1").onclick = () => fill(LIKELY_PATIENT);
document.getElementById("ex2").onclick = () => fill(LIKELY_HEALTHY);
